typedef unsigned short u16;
typedef unsigned int u32;
extern const u32 __album[];
#include "font.h"
#define VRAM ((volatile u16*)0x06000000)
#define REG(a) (*(volatile u16*)(a))
static void dma(const void*src,volatile void*dst,u32 control){*(volatile u32*)0x040000d4=(u32)src;*(volatile u32*)0x040000d8=(u32)dst;*(volatile u32*)0x040000dc=control;}
static void rect(int x,int y,int w,int h,u16 c){volatile u16 color=c;if(w==240){dma((const void*)&color,VRAM+y*240,0x81000000|(w*h));}else for(int j=y;j<y+h;j++)dma((const void*)&color,VRAM+j*240+x,0x81000000|w);}
static void text(int x,int y,const char*s,u16 c){for(;*s;s++,x+=6){unsigned ch=(unsigned char)*s;if(ch<32||ch>126)ch=32;for(int j=0;j<8;j++)for(int i=0;i<5;i++)if(font[ch-32][j]&(1<<i))VRAM[(y+j)*240+x+i]=c;}}
static void number(int x,int y,int n,u16 c){char b[6];int l=0;do{b[l++]=48+n%10;n/=10;}while(n&&l<5);for(int i=l-1;i>=0;i--){char a[2]={b[i],0};text(x,y,a,c);x+=6;}}
static void waitframe(void){while(REG(0x04000006)>=160);while(REG(0x04000006)<160);}
static void picture(int n){const u32 *entry=__album+4+n*9;const volatile u16 *src=(const u16*)((const char*)__album+entry[0]);dma((const void*)src,VRAM,0x80000000|38400);}
static void menu(int n,int count){rect(0,0,240,160,0x1882);rect(0,0,240,22,0x4108);text(10,7,"POCKET IMAGE VIEWER",0x7fff);int start=n/7*7;for(int j=0;j<7&&start+j<count;j++){int k=start+j;int y=29+j*13;if(k==n)rect(6,y-2,228,12,0x6a49);number(12,y,k+1,0x7fff);text(40,y,(const char*)(__album+4+k*9+1),0x7fff);}text(8,130,"PAD SELECT   A VIEW   START SHOW",0x7fff);text(8,145,"SELECT CONTROLS",0x6318);}
static void help(void){rect(0,0,240,160,0x1882);text(10,10,"YOUR PICTURES ON GBA",0x7fff);text(10,32,"L / R       PREVIOUS / NEXT",0x7fff);text(10,46,"A + L / R   SKIP 10",0x7fff);text(10,60,"B + L / R   SKIP 100",0x7fff);text(10,74,"START + R   SLIDESHOW",0x7fff);text(10,88,"A           PAUSE SLIDESHOW",0x7fff);text(10,102,"START + L   IMAGE MENU",0x7fff);text(10,116,"B           BACK TO MENU",0x7fff);text(10,138,"A TO OPEN IMAGE MENU",0x7fff);}
void main(void){REG(0x04000208)=0;REG(0x04000000)=0x403;int count=__album[1],interval=__album[2];int n=0,state=0,old=0,timer=0,paused=0,b_used=0;help();for(;;){waitframe();int keys=(~REG(0x04000130))&1023;int pressed=keys&~old;int released=old&~keys;old=keys;if(pressed&2)b_used=0;if((keys&2)&&(keys&(1|256|512)))b_used=1;int dirty=0;if(pressed&4){state=0;help();continue;}if(state==0){if(pressed&1){state=1;menu(n,count);}continue;}if(state==1){if(pressed&(128|16|256)){n=(n+1)%count;dirty=1;}if(pressed&(64|32|512)){n=(n+count-1)%count;dirty=1;}if(pressed&1){state=2;picture(n);}else if(pressed&8){state=3;timer=0;paused=0;picture(n);}else if(dirty)menu(n,count);continue;}if((released&2)&&!b_used){state=1;menu(n,count);continue;}if((keys&8)&&(pressed&512)){state=1;menu(n,count);continue;}if((keys&8)&&(pressed&256)){state=3;paused=0;timer=0;dirty=1;}else if(pressed&(256|512)){int skip=(keys&1)?10:((keys&2)?100:1);if(pressed&512)skip=-skip;n=(n+skip)%count;if(n<0)n+=count;timer=0;dirty=1;}if((keys&3)==3&&(pressed&3)){n=(n+timer+17)%count;dirty=1;}if(state==3){if(pressed&1)paused=!paused;if(!paused&&++timer>=interval*60){n=(n+1)%count;timer=0;dirty=1;}}if(dirty)picture(n);}}
